    # BR: 270° CW (=90° CCW) rotation of TL
    br_q = rotate_90_cw(rotate_90_cw(rotate_90_cw(tl)))
    for r in range(5):
        for c in range(5):
            result[mr+1+r][mc+1+c] = br_q[r][c]

    # Preserve cross
    for r in range(11):
        result[r][mc] = 4
    for c in range(11):
        result[mr][c] = 4

    return result

